package com.jadhavr.erp.fee.entity;
import com.jadhavr.erp.common.entity.BaseAuditEntity; import com.jadhavr.erp.fee.enums.FeeTransactionType; import com.jadhavr.erp.user.entity.User; import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="fee_transactions") public class FeeTransaction extends BaseAuditEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="fee_account_id",nullable=false) private StudentFeeAccount studentFeeAccount; @ManyToOne(fetch=FetchType.LAZY) private FeePayment feePayment; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private FeeTransactionType transactionType; @Column(nullable=false,precision=12,scale=2) private BigDecimal amount; private BigDecimal previousPaidAmount,newPaidAmount,previousRemainingAmount,newRemainingAmount; @Column(length=500) private String remarks; @ManyToOne(fetch=FetchType.LAZY) private User performedBy; public Long getId(){return id;} public void setId(Long v){id=v;} public StudentFeeAccount getStudentFeeAccount(){return studentFeeAccount;} public void setStudentFeeAccount(StudentFeeAccount v){studentFeeAccount=v;} public FeePayment getFeePayment(){return feePayment;} public void setFeePayment(FeePayment v){feePayment=v;} public FeeTransactionType getTransactionType(){return transactionType;} public void setTransactionType(FeeTransactionType v){transactionType=v;} public BigDecimal getAmount(){return amount;} public void setAmount(BigDecimal v){amount=v;} public BigDecimal getPreviousPaidAmount(){return previousPaidAmount;} public void setPreviousPaidAmount(BigDecimal v){previousPaidAmount=v;} public BigDecimal getNewPaidAmount(){return newPaidAmount;} public void setNewPaidAmount(BigDecimal v){newPaidAmount=v;} public BigDecimal getPreviousRemainingAmount(){return previousRemainingAmount;} public void setPreviousRemainingAmount(BigDecimal v){previousRemainingAmount=v;} public BigDecimal getNewRemainingAmount(){return newRemainingAmount;} public void setNewRemainingAmount(BigDecimal v){newRemainingAmount=v;} public String getRemarks(){return remarks;} public void setRemarks(String v){remarks=v;} public User getPerformedBy(){return performedBy;} public void setPerformedBy(User v){performedBy=v;} }
